<?php declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('GET'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$q=fn(string $sql)=>(int)$db->query($sql)->fetchColumn();$data=['total_products'=>$q('SELECT COUNT(*) FROM products'),'active_products'=>$q("SELECT COUNT(*) FROM products WHERE status='ACTIVE'"),'categories'=>$q('SELECT COUNT(*) FROM categories'),'low_stock_products'=>$q("SELECT COUNT(*) FROM products WHERE manage_inventory=1 AND stock_quantity>0 AND stock_quantity<=low_stock_threshold"),'out_of_stock_products'=>$q("SELECT COUNT(*) FROM products WHERE manage_inventory=1 AND stock_quantity<=0"),'orders'=>$q('SELECT COUNT(*) FROM orders'),'pending_orders'=>$q("SELECT COUNT(*) FROM orders WHERE order_status IN ('NEW','CONFIRMED')"),'active_coupons'=>$q("SELECT COUNT(*) FROM coupons WHERE status='ACTIVE'"),'new_enquiries'=>$q("SELECT COUNT(*) FROM enquiries WHERE status='NEW'")];$data['recent_orders']=$db->query('SELECT * FROM orders ORDER BY created_at DESC LIMIT 5')->fetchAll();$data['recent_enquiries']=$db->query('SELECT * FROM enquiries ORDER BY created_at DESC LIMIT 5')->fetchAll();$data['low_stock_items']=$db->query("SELECT id,name,stock_quantity,low_stock_threshold FROM products WHERE manage_inventory=1 AND stock_quantity<=low_stock_threshold ORDER BY stock_quantity LIMIT 10")->fetchAll();jsonResponse(true,'Dashboard loaded.',$data);});
